package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Category string `json:"category"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Build base query
	query := "SELECT id, name, price, category FROM products WHERE 1=1"

	if category != "" {
		// Parameterized - safe
		query += " AND category = $1"
	}

	if minPrice != "" {
		// Parameterized - safe
		query += " AND price >= $2"
	}

	// Sort handling - VULNERABLE: sortBy injected directly
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortBy != "" {
		if allowedSorts[strings.ToLower(sortBy)] {
			query += " ORDER BY " + sortBy
		} else {
			// Developer intended to reject unknown sorts but instead
			// falls through with user input for "complex" sort expressions
			if strings.Contains(sortBy, ",") {
				// Multi-column sort: user passes "name,price" -> allows injection
				query += " ORDER BY " + sortBy
			}
		}
	} else {
		query += " ORDER BY id"
	}

	query += " LIMIT 50"

	var rows *sql.Rows
	var err error

	switch {
	case category != "" && minPrice != "":
		rows, err = db.Query(query, category, minPrice)
	case category != "":
		rows, err = db.Query(query, category)
	case minPrice != "":
		rows, err = db.Query(query, minPrice)
	default:
		rows, err = db.Query(query)
	}

	if err != nil {
		http.Error(w, "Internal error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	fmt.Fprintf(w, "ok")
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
